function canEditNotes(){return !window.PermissionService||PermissionService.can('communication.notes.edit','edit')}
const NOTE_COLORS=['sari','yesil','mavi','mor','turuncu','pembe','gri'];
const NOTE_TYPES={metin:{icon:'📝',label:'Metin'},todo:{icon:'✅',label:'Yapılacaklar'},cizim:{icon:'✏️',label:'Çizim'},goruntu:{icon:'🖼️',label:'Görsel'},tablo:{icon:'📊',label:'Tablo'}};
function noteType(x){return NOTE_TYPES[x?.tip]||NOTE_TYPES.metin}
function noteOwnerName(x){if(!x?.sahipUid||x.sahipUid===uid()){const u=currentUser();return String(u.adSoyad||[u.ad,u.soyad].filter(Boolean).join(' ')||u.displayName||u.kullaniciAdi||'Ben').trim()}return announcementReaderName(x.sahipUid,{})}
function noteSafeHtml(x){const raw=String(x?.icerik||x?.not||'');return window.NotlarService?.sanitizeHtml?.(raw)||''}
function notePlainText(x){const raw=noteSafeHtml(x);if(typeof document==='undefined')return raw.replace(/<[^>]*>/g,' ');const d=document.createElement('div');d.innerHTML=raw;return String(d.textContent||'').replace(/\s+/g,' ').trim()}
function visibleNotes(){const u=currentUser();return (u.admin===true?arr('notlar'):arr('notlar').filter(x=>x.sahipUid===uid())).filter(x=>match([x.baslik,notePlainText(x),(x.etiketler||[]).join(' '),(x.maddeler||[]).map(noteItemText).join(' '),x.sahipUid?noteOwnerName(x):'']))}
function noteItemText(m){return typeof m==='string'?m:String(m?.metin||m?.text||m?.ad||'')}
function noteItemDone(m){return !!(m&&typeof m==='object'&&(m.tamamlandi===true||m.completed===true||m.bitti===true))}
function noteDate(x){return date(x?.tarih||x?.guncellenmeTarihi||x?.eklenmeTarihi)||'—'}
function noteTypePreview(x,{full=false,interactive=false}={}){const type=noteType(x),items=Array.isArray(x.maddeler)?x.maddeler:[];if(x.tip==='todo'){const rows=full?items:items.slice(0,3);return `<div class="ka-note-todo-preview">${rows.map((m,i)=>interactive?`<label class="ka-note-todo-row"><input type="checkbox" data-note-item="${esc(x.id)}" data-note-index="${i}" ${noteItemDone(m)?'checked':''} ${canEditNotes()?'':'disabled'}><span>${esc(noteItemText(m)||`Madde ${i+1}`)}</span></label>`:`<div class="ka-note-todo-row"><span class="ka-note-todo-mark">${noteItemDone(m)?'☑':'☐'}</span><span class="${noteItemDone(m)?'is-done':''}">${esc(noteItemText(m)||`Madde ${i+1}`)}</span></div>`).join('')}${!full&&items.length>3?`<small>+${items.length-3} madde daha</small>`:''}</div>`}if(x.tip==='cizim'&&x.cizimData)return `<div class="ka-note-media-preview"><img src="${esc(x.cizimData)}" alt="Çizim"></div>`;if(x.tip==='goruntu'&&x.goruntu)return `<div class="ka-note-media-preview"><img src="${esc(x.goruntu)}" alt="Görsel not"></div>`;if(x.tip==='tablo'&&Array.isArray(x.tabloVeri)){const rows=full?x.tabloVeri:x.tabloVeri.slice(0,3);return `<div class="ka-note-table-preview"><table><tbody>${rows.map((r,ri)=>`<tr>${(r||[]).map(c=>`<${ri===0?'th':'td'}>${esc(c||'')}</${ri===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`}if(x.tip==='metin'||!x.tip){const html=noteSafeHtml(x);return html?`<div class="ka-note-rich-preview${full?' is-full':''}">${html}</div>`:''}return `<div class="ka-muted">${esc(type.label)} içeriği</div>`}
function noteTags(x){const tags=Array.isArray(x.etiketler)?x.etiketler.filter(Boolean):[];return tags.length?`<div class="ka-note-tags">${tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}
function noteCard(x,{showOwner=false}={}){const type=noteType(x),items=Array.isArray(x.maddeler)?x.maddeler:[],done=items.filter(noteItemDone).length,color=NOTE_COLORS.includes(x.renk)?x.renk:'sari';return `<article class="ka-note-card" data-note-card="${esc(x.id)}" data-note-open="${esc(x.id)}" data-note-color="${color}" role="button" tabindex="0"><div class="ka-note-card__open"><div class="ka-note-card__head"><div class="ka-note-type"><span>${type.icon}</span><small>${esc(type.label)}</small></div><strong>${esc(x.baslik||'(Başlıksız)')}</strong><span class="ka-note-card__date">${esc(noteDate(x))}</span></div><div class="ka-note-card__preview">${noteTypePreview(x)}</div>${noteTags(x)}${showOwner?`<div class="ka-note-owner">👤 ${esc(noteOwnerName(x))}</div>`:''}${items.length?`<div class="ka-note-progress">${done}/${items.length} tamamlandı</div>`:''}</div>${canEditNotes()?`<div class="ka-note-card__actions"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-note-edit="${esc(x.id)}">Düzenle</button><button class="ka-btn ka-btn--ghost ka-btn--sm" type="button" data-note-delete="${esc(x.id)}">Sil</button></div>`:''}</article>`}
function notes(){const l=visibleNotes().sort((a,b)=>String(b.guncellenmeTarihi||b.eklenmeTarihi||'').localeCompare(String(a.guncellenmeTarihi||a.eklenmeTarihi||''))),me=uid(),admin=currentUser().admin===true,mine=admin?l.filter(x=>!x.sahipUid||x.sahipUid===me):l,others=admin?l.filter(x=>x.sahipUid&&x.sahipUid!==me):[],pending=mine.filter(x=>x.tip==='todo').reduce((n,x)=>n+(x.maddeler||[]).filter(m=>!noteItemDone(m)).length,0),month=new Date().toISOString().slice(0,7),thisMonth=mine.filter(x=>String(x.tarih||x.eklenmeTarihi||'').slice(0,7)===month).length;const group=(title,list,showOwner=false)=>list.length?`<section class="ka-notes-group">${title?`<div class="ka-notes-group__head"><h3>${title}</h3><span class="ka-badge">${list.length}</span></div>`:''}<div class="ka-notes-grid">${list.map(x=>noteCard(x,{showOwner})).join('')}</div></section>`:'';return{count:l.length,html:`<section class="ka-notes-workspace"><header class="ka-notes-hero"><div><span class="ka-notes-kicker">KİŞİSEL NOT DEFTERİ</span><h1>Notlarım</h1><p>Metin, yapılacaklar, çizim, görsel ve tablolarınızı tek yerde yönetin.</p></div>${canEditNotes()?'<button class="ka-btn ka-btn--lg" type="button" data-note-add>+ Yeni Not</button>':''}</header><div class="ka-notes-summary"><article><span>🗒️</span><div><small>Toplam Not</small><b>${mine.length}</b></div></article><article><span>✓</span><div><small>Bekleyen İş</small><b>${pending}</b></div></article><article><span>📅</span><div><small>Bu Ay</small><b>${thisMonth}</b></div></article></div>${admin&&others.length?group('📌 Benim Notlarım',mine)+group('👥 Diğer Kullanıcıların Notları',others,true):group('',l)}${!l.length?'<div class="ka-empty">Henüz not eklenmedi.</div>':''}</section>`}}
function noteDetailModal(item){const type=noteType(item);return `<div class="ka-modal-backdrop" data-note-detail><section class="ka-modal ka-note-detail"><div class="ka-modal__header"><div><div class="ka-note-detail__meta"><span>${type.icon} ${esc(type.label)}</span><span>${esc(noteDate(item))}</span></div><h2>${esc(item.baslik||'(Başlıksız)')}</h2></div><button class="ka-icon-button" type="button" data-note-close aria-label="Kapat">×</button></div><div class="ka-modal__body ka-stack">${noteTypePreview(item,{full:true,interactive:item.tip==='todo'})}${noteTags(item)}${currentUser().admin===true&&item.sahipUid&&item.sahipUid!==uid()?`<div class="ka-note-owner">👤 ${esc(noteOwnerName(item))} tarafından eklendi</div>`:''}</div>${canEditNotes()?`<div class="ka-modal__footer"><button class="ka-btn ka-btn--danger" type="button" data-note-delete="${esc(item.id)}">Sil</button><button class="ka-btn" type="button" data-note-edit="${esc(item.id)}">Düzenle</button></div>`:''}</section></div>`}
function openNoteDetail(item){document.querySelector('[data-note-detail]')?.remove();document.body.insertAdjacentHTML('beforeend',noteDetailModal(item));const modal=document.querySelector('[data-note-detail]');modal.querySelector('[data-note-close]')?.addEventListener('click',()=>modal.remove());modal.addEventListener('click',e=>{if(e.target===modal)modal.remove()});modal.querySelector('[data-note-edit]')?.addEventListener('click',()=>{modal.remove();openNoteModal(item)});modal.querySelector('[data-note-delete]')?.addEventListener('click',async()=>{modal.remove();await deleteNote(item.id)});modal.querySelectorAll('[data-note-item]').forEach(c=>c.addEventListener('change',()=>toggleNoteItem(c.dataset.noteItem,Number(c.dataset.noteIndex),c.checked)))}
function noteCommonFields(item){const color=NOTE_COLORS.includes(item.renk)?item.renk:'sari';return `<input type="hidden" name="id" value="${esc(item.id||'')}"><input type="hidden" name="tip" value="${esc(item.tip||'metin')}"><label class="ka-field"><span class="ka-field__label">Başlık</span><input name="baslik" maxlength="160" value="${esc(item.baslik||'')}" placeholder="Not başlığı…"></label><div class="ka-field"><span class="ka-field__label">Renk</span><div class="ka-note-color-picker">${NOTE_COLORS.map(c=>`<button type="button" class="ka-note-color ${c===color?'active':''}" data-note-color-pick="${c}" data-note-color="${c}" aria-label="${c}"></button>`).join('')}</div><input type="hidden" name="renk" value="${color}"></div><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Etiketler</span><input name="etiketler" value="${esc((item.etiketler||[]).join(', '))}" placeholder="önemli, toplantı…"></label><label class="ka-field"><span class="ka-field__label">Tarih</span><input type="date" name="tarih" value="${esc(item.tarih||new Date().toISOString().slice(0,10))}"></label></div>`}
function noteTodoRows(items=[]){const rows=items.length?items:[{metin:'',tamamlandi:false}];return rows.map((m,i)=>`<div class="ka-note-todo-edit-row" data-note-todo-row><input type="checkbox" data-note-todo-done ${noteItemDone(m)?'checked':''}><input type="text" data-note-todo-text value="${esc(noteItemText(m))}" placeholder="Yapılacak madde…"><button type="button" class="ka-icon-button" data-note-todo-remove aria-label="Maddeyi sil">×</button></div>`).join('')}
function noteTableHtml(rows,cols,values=[]){let h='<table><tbody>';for(let r=0;r<rows;r++){h+='<tr>';for(let c=0;c<cols;c++){const v=values?.[r]?.[c]||'';h+=`<${r===0?'th':'td'}><input data-note-table-cell data-r="${r}" data-c="${c}" value="${esc(v)}" placeholder="${r===0?'Başlık '+(c+1):'…'}"></${r===0?'th':'td'}>`}h+='</tr>'}return h+'</tbody></table>'}
function noteEditorBody(item){const tip=item.tip||'metin';if(tip==='todo')return `<div class="ka-field"><span class="ka-field__label">Yapılacaklar</span><div class="ka-note-todo-editor" data-note-todo-list>${noteTodoRows(item.maddeler||[])}</div><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-note-todo-add>+ Madde Ekle</button></div>`;if(tip==='cizim')return `<div class="ka-field"><span class="ka-field__label">Çizim</span><div class="ka-note-drawing-toolbar"><div class="ka-note-drawing-tools"><button class="ka-btn ka-btn--secondary ka-btn--sm active" type="button" data-draw-tool="pen">✏️ Kalem</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-draw-tool="brush">🖌️ Fırça</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-draw-tool="highlighter">🖍️ İşaretleyici</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-draw-tool="eraser">🧹 Silgi</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-draw-tool="pan">🤚 Kaydır</button></div><div class="ka-note-drawing-controls"><input type="color" data-draw-color value="#1A2A2A" aria-label="Çizim rengi"><select data-draw-size aria-label="Kalınlık"><option value="2">2 px</option><option value="4" selected>4 px</option><option value="8">8 px</option><option value="16">16 px</option></select><select data-draw-bg aria-label="Zemin"><option value="#ffffff">Beyaz</option><option value="#FEF9C3">Sarı</option><option value="#DCFCE7">Yeşil</option><option value="#DBEAFE">Mavi</option><option value="#F3F4F6">Gri</option><option value="#1C1C1C">Koyu</option></select><select data-draw-template aria-label="Şablon"><option value="plain">Düz</option><option value="lined">Çizgili</option><option value="grid">Kareli</option><option value="dots">Noktalı</option><option value="notebook">Defter</option></select><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-draw-undo>↩ Geri Al</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-draw-clear>Temizle</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-draw-fullscreen>⛶ Tam Ekran</button></div></div><div class="ka-note-drawing-stage"><canvas data-draw-canvas width="900" height="560"></canvas></div><small class="ka-muted">İki parmakla yakınlaştır/uzaklaştır · 🤚 ile kaydır</small></div>`;if(tip==='goruntu')return `<div class="ka-field"><span class="ka-field__label">Görsel</span><label class="ka-note-image-picker"><input type="file" accept="image/*" data-note-image-input><div data-note-image-preview>${item.goruntu?`<img src="${esc(item.goruntu)}" alt="Görsel not">`:'<span>🖼️ Görsel seçmek için dokunun</span>'}</div></label><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-note-image-remove>Görseli Kaldır</button></div>`;if(tip==='tablo'){const rows=Math.max(1,Math.min(20,Number(item.tabloSatir)||item.tabloVeri?.length||3)),cols=Math.max(1,Math.min(10,Number(item.tabloSutun)||item.tabloVeri?.[0]?.length||3));return `<div class="ka-field"><span class="ka-field__label">Tablo</span><div class="ka-note-table-size"><label>Satır <input type="number" min="1" max="20" value="${rows}" data-note-table-rows></label><label>Sütun <input type="number" min="1" max="10" value="${cols}" data-note-table-cols></label></div><div class="ka-note-table-editor" data-note-table-wrap>${noteTableHtml(rows,cols,item.tabloVeri||[])}</div></div>`}return `<div class="ka-field"><span class="ka-field__label">İçerik</span><div class="ka-note-editor-toolbar"><button type="button" data-note-command="bold"><b>K</b></button><button type="button" data-note-command="italic"><i>İ</i></button><button type="button" data-note-command="underline"><u>A</u></button><button type="button" data-note-block="h2">B1</button><button type="button" data-note-block="h3">B2</button><button type="button" data-note-command="insertUnorderedList">• ≡</button><button type="button" data-note-command="insertOrderedList">1. ≡</button><button type="button" data-note-command="justifyLeft">⬅</button><button type="button" data-note-command="justifyCenter">⬌</button><button type="button" data-note-command="justifyRight">➡</button><button type="button" data-note-link>🔗</button><button type="button" data-note-command="removeFormat">✕</button></div><div class="ka-note-rich-editor" data-note-rich contenteditable="true" spellcheck="true">${noteSafeHtml(item)}</div></div>`}
function noteModal(item={}){const type=noteType(item);return `<div class="ka-modal-backdrop" data-note-modal><form class="ka-modal ka-note-modal" id="noteForm"><div class="ka-modal__header"><div><span class="ka-note-modal__type">${type.icon} ${esc(type.label)}</span><h2>${item.id?'Notu Düzenle':'Yeni Not'}</h2></div><button class="ka-icon-button" type="button" data-note-close aria-label="Kapat">×</button></div><div class="ka-modal__body ka-stack">${noteCommonFields(item)}${noteEditorBody(item)}</div><div class="ka-modal__footer"><button class="ka-btn ka-btn--secondary" type="button" data-note-close>Vazgeç</button><button class="ka-btn" type="submit">Kaydet</button></div></form></div>`}
