function collectNotePayload(modal,item){const form=modal.querySelector('#noteForm'),fd=new FormData(form),tip=String(fd.get('tip')||item.tip||'metin'),baslik=String(fd.get('baslik')||'').trim(),renk=String(fd.get('renk')||'sari'),tarih=String(fd.get('tarih')||new Date().toISOString().slice(0,10)),etiketler=String(fd.get('etiketler')||'').split(',').map(x=>x.trim()).filter(Boolean),v={baslik,tip,renk,tarih,etiketler};if(tip==='metin'){const editor=modal.querySelector('[data-note-rich]');v.icerik=editor?.innerHTML||'';if(!baslik&&!String(editor?.textContent||'').trim())throw new Error('Başlık veya içerik girilmelidir.')}else if(tip==='todo'){v.maddeler=[...modal.querySelectorAll('[data-note-todo-row]')].map(r=>({metin:r.querySelector('[data-note-todo-text]')?.value.trim()||'',tamamlandi:!!r.querySelector('[data-note-todo-done]')?.checked})).filter(x=>x.metin);if(!baslik&&!v.maddeler.length)throw new Error('En az bir madde veya başlık girilmelidir.')}else if(tip==='cizim'){v.cizimData=modal._noteDrawingExport?.()||item.cizimData||''}else if(tip==='goruntu')v.goruntu=modal._noteImageData||'';else if(tip==='tablo'){v.tabloVeri=readNoteTable(modal);v.tabloSatir=Math.max(1,Number(modal.querySelector('[data-note-table-rows]')?.value)||3);v.tabloSutun=Math.max(1,Number(modal.querySelector('[data-note-table-cols]')?.value)||3)}return v}
