const GOREV_DURUM_LABEL={yapilacak:'Yapılacak','devam ediyor':'Devam Ediyor',tamamlandi:'Tamamlandı'};
function canEditCalendar(){return !window.PermissionService||PermissionService.can('communication.calendar.edit','edit')}
